{ q:'سمّي التلات Ps الزيادة للخدمات.', a:'People (الناس)، وprocess (طريقة التقديم)، وphysical evidence (الدليل الملموس).', why:'الخدمات بيقدّمها ناس في process، فدول بيشكّلوا التجربة زي السعر والإعلانات بالظبط.', k:[['People',['people','الناس']],['Process',['process']],['Physical evidence',['physical evidence','الدليل']]] },
{ q:'اديني فرقين بين الشرا في الـ B2B والـ B2C.', a:'أي اتنين: الـ B2B فيه مشترين أقل وأكبر؛ وكذا شخص بيقرر؛ ودورات أطول؛ وتركيز أكتر على الـ ROI والمخاطرة؛ والعلاقات بتفرق أكتر. الـ B2C مشترين كتير، وواحد أو اتنين بيقرروا، وأسرع، ووزن أكبر للعاطفة والسهولة.', why:'المبادئ واحدة؛ وزن كل تكتيك هو اللي بيتغيّر.', k:[['عدد أو حجم المشترين',['اقل','اكبر','كتير','عدد']],['كذا شخص بيقرر',['كذا شخص','بيقرروا','اكتر من شخص']],['دورة أطول',['اطول','دوره']],['الـ ROI أو المخاطرة أو العاطفة',['roi','مخاطره','عاطفه']]] },
{ q:'اكتب الست حاجات اللي في الاستراتيجية في صفحة واحدة.', a:'العميل المستهدف، ومشكلته، وتموضعك، والعرض بتاعك، وأهم قناتين، ورقم هدف واحد.', why:'لو مش قادر تملا صفحة واحدة، يبقى مش جاهز تصرف.', k:[['العميل المستهدف',['المستهدف','الهدف','target']],['المشكلة',['مشكل']],['التموضع',['تموضع','position']],['العرض',['العرض','offer']],['قناتين',['قناتين','قنوات','channel']],['رقم هدف واحد',['رقم','هدف واحد']]] },
{ q:'أنهي استراتيجية وأنهي تكتيك في كيستريل؟ (1) تركّز على أصحاب البيوت اللي أجهزتهم عندها 10 سنين أو أكتر؛ (2) كارت بوستال للعملاء القدام في أكتوبر؛ (3) تبقى أكتر اسم محلي موثوق في تغيير الأجهزة؛ (4) إعلان فيسبوك للصيانة.', a:'استراتيجية: 1 و3. تكتيك: 2 و4.', why:'الاستراتيجية هي اختيار مين وتكسب إزاي. والتكتيك هو الأفعال المحددة.', k:[['1 و3 استراتيجية',['استراتيجيه']],['2 و4 تكتيك',['تكتيك']]] },
{ q:'33% بس من عروض أسعار تغيير الأجهزة في كيستريل بتتحول لبيع، والعملاء بيستنوا يوم عشان حد يرجّعلهم. أنهي P من السبعة هي المشكلة، وإيه تصليح واحد؟', a:'الـ Process. تصليح واحد: ابعت عرض سعر مكتوب بصور واختيارين أو تلاتة قبل ما الفني يمشي، وتابع في نفس اليوم، وتاني خلال 48 ساعة.', why:'المشكلة في إزاي الخدمة بتتقدّم بعد الزيارة، مش في الإعلانات ولا السعر.', k:[['Process',['process']],['تصليح في التقديم (عرض أسرع أو متابعة)',['متابع','اسرع','نفس اليوم','مكتوب','48']]] },
{ q:'قيّم شريحة جديدة لكيستريل من 1 لـ 5 على الحجم والقيمة والاستعجال والوصول وميزتنا: أصحاب البيوت في كمبوند ريدج فيو الجديد، اللي كل بيوته اتبنت سنة 2023. اديني المجموع وقرار.', a:'مثال: الحجم 2، والقيمة 2، والاستعجال 1 (أجهزة جديدة تحت الضمان)، والوصول 5 (حي واحد)، والميزة 2. المجموع 12 من 25. مش دلوقتي؛ ارجعلهم بعد كام سنة لما الضمانات تخلص، أو اعرض عليهم صيانة Comfort Club كتواصل خفيف ورخيص.', why:'سهولة الوصول مش بتخلّي الشريحة هدف كويس لو لسه مش محتاجينك.', k:[['مجموع حوالي 12 (قليل)',['12']],['استعجال قليل أو تحت الضمان',['الضمان','ضمان','استعجال']],['مش دلوقتي، أو تواصل خفيف بعدين',['مش دلوقتي','بعدين','خفيف','بعد كام سنه']]] },
{ q:'كيستريل بتاخد 89 دولار كشف، وبيتلغي لو العميل كمّل في التصليح. ده بيعمل إيه في الـ P بتاعة السعر، وإيه المخاطرة اللي تراقبها؟', a:'بيقلّل الحاجز قدام الحجز وبيوصّل إحساس بالعدل (بتدفع الكشف بس لو ماكمّلتش)، وفي نفس الوقت بيغطّي تكلفة الزيارات اللي مبيطلعش منها شغل. المخاطرة: ممكن يجيب ناس بتدوّر على السعر بس، بيحجزوا كشف ومبيصلّحوش أبدا. راقب نسبة زيارات الكشف اللي بتتحول لتصليح.', why:'السعر رسالة مش بس رقم. تابع إذا كانت قاعدة التسعير بتجيب العملاء الصح.', k:[['بيقلّل الحاجز أو بيوصّل عدل',['الحاجز','عدل','اسهل','بيقلل']],['بيغطّي الزيارات اللي مفيهاش شغل',['بيغطي','تكلفه الزيارات','مفيهاش شغل','مبيطلعش']],['المخاطرة: ناس بتدوّر على السعر',['السعر بس','بيدوروا علي السعر','مبيصلحوش']],['تتابع الكشف اللي بيتحول',['نسبه','بتتحول','راقب','تتابع']]] },
{ q:'اكتب تلات حاجات physical evidence كيستريل تقدر تضيفهم لعروض أسعار تغيير الأجهزة عشان ترفع نسبة القفل.', a:'أي تلاتة: صور الجهاز الحالي والمشكلة اللي اتلاقت؛ ومقارنة مكتوبة بين اختيارين أو تلاتة؛ وتقييمات من جيران غيّروا مع كيستريل؛ وتقدير للتوفير في الطاقة؛ وورقة الضمان؛ وشهادات الفني.', why:'الشرا الكبير محتاج إثبات العميل يمسكه، ويورّيه لشريكه، ويقارن بيه.', k:[['صور الجهاز أو المشكلة',['صور','صوره']],['اختيارات مكتوبة أو مقارنة',['مقارنه','اختيارات','مكتوب']],['تقييمات أو جيران',['تقييم','جيران']],['ضمان أو توفير أو شهادات',['ضمان','توفير','شهادات']]] },
{ q:'كيستريل قررت تستهدف شركات إدارة العقارات (B2B). الـ people والـ process والسعر والـ physical evidence المفروض يتغيّروا إزاي معاهم؟', a:'People: شخص واحد مسؤول عن الحساب باسمه. Process: وقت استجابة بأولوية، وأوامر شغل بالإيميل أو بورتال، وفواتير شهرية. السعر: أسعار متفق عليها أو عقد على وحدات كتير. Physical evidence: تقارير شغل بالصور لكل وحدة، بتتبعت للمدير وللمالك.', why:'مشترين الـ B2B محتاجين اعتمادية وتقارير وشروط تناسب طريقة إدارتهم للبيزنس.', k:[['شخص مسؤول باسمه (people)',['شخص','مسؤول','باسمه']],['استجابة بأولوية أو process أبسط',['اولويه','استجابه','بورتال','فواتير']],['أسعار متفق عليها أو عقد',['متفق','عقد']],['تقارير أو صور (evidence)',['تقارير','صور']]] },
{ q:'اكتب الاستراتيجية في صفحة واحدة لكيستريل عشان تكبّر Comfort Club في الست شهور الجايين.', a:'مثال. الهدف: العملاء الحاليين اللي أجهزتهم عندها 8 سنين أو أكتر. المشكلة: أعطال في أوحش وقت ومحدش بيفكّرهم بالصيانة. التموضع: الاشتراك المحلي اللي بيخلّيك أول واحد في الدور. العرض: 15 دولار في الشهر بصيانتين في السنة وأولوية في الحجز. القنوات: العرض في آخر كل زيارة خدمة، وإيميلات وكروت بوستال للعملاء القدام. الهدف الرقمي: من 1,000 لـ 1,200 مشترك.', why:'حتى برنامج واحد محتاج هدف ومشكلة وتموضع وعرض وقناتين ورقم واحد.', k:[['الهدف متسمّي',['العملا الحاليين','الهدف','8 سنين','اصحاب']],['المشكلة متسمّية',['مشكل','اعطال']],['العرض متسمّي',['15','عرض','صيانتين']],['قناتين',['ايميل','كروت','زياره','قنوات']],['رقم هدف واحد',['1,200','1200']]] },
{ q:'الشغل التجاري الخفيف بيدفع كويس، ومنافس مشغول بيه. دانا عايزة تستهدفه دلوقتي. بجدول التقييم، هتنصح بإيه، وإيه اللي يغيّر رأيك؟', a:'مش دلوقتي. التجاري الخفيف واخد 13 من 25، أساسا لأن كيستريل لسه معندهاش ميزة هناك (1 من 5) وصعب توصلهم. ركّز على شريحة أصحاب البيوت بالـ 22 نقطة الأول. اللي يغيّر رأيي: فني متدرّب على التجاري، أو كام عميل تجاري محلي يشهدوا، أو عقد يسهّل الوصول ليهم.', why:'القيمة العالية لوحدها مبتعملش هدف كويس. محتاج تقدر توصل الشريحة وتكسب البدايل.', k:[['مش دلوقتي، أو أصحاب البيوت الأول',['مش دلوقتي','اصحاب البيوت','22']],['ميزة قليلة أو صعب الوصول',['ميزه','صعب','1 من 5','13']],['إيه اللي يغيّر رأيك',['فني متدرب','يغير رايي','عقد','عملا تجاريين','يشهدوا']]] },
{ q:'وكالة بتقترح TikTok وبودكاست وإنستجرام وإعلانات جوجل لكيستريل، كلهم مرة واحدة، بـ 8,000 دولار في الشهر. أنهي سؤالين من الاستراتيجية في صفحة هتسألهم قبل ما توافق، وليه؟', a:'1) مين الهدف بالظبط، وهل بيستخدموا القنوات دي؟ أصحاب البيوت اللي أجهزتهم قديمة غالبا بيدوّروا ويقروا تقييمات لما يحتاجوا مساعدة. 2) إيه رقم الهدف الواحد، وكل قناة هتتقاس عليه إزاي؟ من غير هدف ورقم، أربع قنوات مرة واحدة مينفعش يتحكم عليهم، والفلوس بتتفرّق.', why:'الاستراتيجية الأول: الهدف والرقم هما اللي بيحددوا القنوات، مش العكس.', k:[['مين الهدف',['مين الهدف','الهدف بالظبط','اصحاب البيوت','target']],['الرقم أو هيتقاس إزاي',['رقم','هتتقاس','قياس','goal']],['قنوات كتير مرة واحدة',['مره واحده','اربع قنوات','بتتفرق','كتير']]] },
{ q:'دانا عايزة تقسم الـ 6,000 دولار في الشهر بالنص بين أصحاب البيوت وشركات إدارة العقارات. اعمل الحجة مع أو ضد بالتقييمات وفروق الـ B2B.', a:'ضد التقسيم بالنص. أصحاب البيوت واخدين 22 ومجرّبين؛ وشركات إدارة العقارات واخدين 16، ودورة الشرا عندهم أطول، ومحتاجين شخص مسؤول وعقود، وهيتكسبوا بالـ outbound والعلاقات أكتر من الإعلانات. خلّي أغلب الميزانية على أصحاب البيوت، واعمل تجربة صغيرة بمدة محددة مع شركات إدارة العقارات (مثلا: تكلّم 20 مدير محلي في 90 يوم بهدف واضح، زي 3 حسابات تمضي).', why:'تقسيم الفلوس بالتساوي على أهداف مش متساوية بيجوّع القوي. جرّب الشريحة الجديدة برخص الأول.', k:[['تقييم 22 قصاد 16',['22','16']],['الـ B2B محتاج طريقة تانية (أطول، علاقات، outbound)',['اطول','علاقات','outbound','عقود']],['أغلب الميزانية على أصحاب البيوت',['اغلب','اصحاب البيوت']],['تجربة صغيرة بهدف',['تجربه','90 يوم','هدف','20 مدير']]] },
{ q:'منافس بيعمل كشف ببلاش. كيستريل تلغي الـ 89 دولار بتوعها؟ افترض إن حوالي 25 زيارة في الشهر كشف بس. احسب إيه اللي على المحك، وهتقرر إزاي.', a:'حوالي 25 × 89 = 2,225 دولار إيراد في الشهر على المحك. متخمّنش: جرّب الكشف ببلاش في جزء من منطقة الخدمة، أو لمشتركين Comfort Club بس، لمدة شهر. قيس نسبة الحجز، وكام كشف ببلاش اتحول لتصليح، والشغلانات الزيادة اللي اتكسبت. خلّي التغيير بس لو الربح الزيادة أكبر من حوالي 2,225 دولار في الشهر.', why:'إنك تعمل زي سعر المنافس من غير أرقام ممكن يضيّع فلوس. حط قيمة للتغيير وجرّبه.', k:[['حوالي 2,225 في الشهر على المحك',['2,225','2225']],['تجرّب قبل ما تقرر (منطقة، مشتركين، شهر)',['جرب','تجربه','شهر','منطقه','مشتركين']],['تقيس الحجز والتحويل لتصليح',['قيس','نسبه الحجز','اتحول','تحويل']],['تخلّيه بس لو الربح أكبر من التكلفة',['اكبر من','الربح الزياده','بس لو']]] },
{ q:'ليه برايت لاين متقدرش تستخدم رسالة زي بتاعة كيستريل (“تصليح في نفس اليوم، اتصل قبل الضهر”) عشان تكسب مستثمرين الأراضي؟', a:'برايت لاين بتبيع B2B: المشتري بيوزن الـ ROI والمخاطرة، وغالبا عنده شريك لازم يقنعه، وبياخد حوالي 3 أسابيع عشان يقرر. محتاجين إثبات العائد (مواعيد اتحجزت، تكلفة الميعاد)، وتسجيلات مكالمات، وتقارير، وبداية مخاطرتها قليلة، مش نداء مستعجل.', why:'قرارات الـ B2B أبطأ، وفيها ناس أكتر، وبتعتمد على الـ ROI والمخاطرة، فالرسالة والإثبات بيتغيّروا.', k:[['كذا شخص أو شريك بيقرر',['شريك','كذا شخص']],['تركيز على الـ ROI أو المخاطرة',['roi','مخاطره','العائد']],['محتاج إثبات (تسجيلات، تقارير)',['تسجيلات','تقارير','اثبات']],['قرار أطول',['3 اسابيع','ابطا','اطول']]] },
{ q:'الجدول بيدي أصحاب البيوت اللي أجهزتهم قديمة 22 نقطة، بس إحساس دانا بيقول “أصحاب البيوت الجداد محتاجين كل حاجة.” إيه البيانات اللي تحسمها قبل ما تغيّر الخطة؟', a:'كام واحد اشترى بيت جديد في المنطقة (الحجم)، وأعمار أجهزتهم إيه (من إعلانات البيوت أو سجلات كيستريل لشغلانات في بيوت اتباعت قريب)، والملاك الجداد بيشتروا إيه فعلا في أول سنتين (غالبا فحص وتصليحات اتلاقت وقت البيع)، وحملة تجربة صغيرة لأصحاب البيوت الجداد، يتحكم عليها بتكلفة الشغلانة.', why:'التقييمات أحكام. لما حد يعترض، حط عدّ وتجربة صغيرة مكان التخمين.', k:[['تعدّ الشريحة (كام مشتري)',['كام واحد','الحجم','عدد']],['أعمار الأجهزة أو بيشتروا إيه',['اعمار','بيشتروا','سجلات']],['حملة تجربة صغيرة',['تجربه','حمله']],['تحكم بتكلفة الشغلانة',['تكلفه الشغلانه','cost per job','تكلفه']]] }
